const CREATED_AT = '2026-08-11T05:36:00.000Z';
const RECOMMENDED_USE = 'Names of God teaching, Give One Catalogue and product artwork, book or chapter visuals, campaign graphics, and social media.';
const CROP = 'Square centered artwork with strong product-card, teaching-card, and social-media crop flexibility.';

function teachingMark({ id, url, title, question, tag, sourceOriginalPath, sourceNote = 'User-supplied square teaching artwork, faithfully vectorized from the uploaded PNG for crisp web reuse.' }) {
  return {
    id,
    url,
    filename: url.split('/').at(-1),
    title,
    alt: `Blue IZHE wordmark with the question ${question}`,
    category: 'teaching',
    usageStatus: 'draft',
    rightsStatus: 'unverified',
    productAccuracyStatus: 'not_applicable',
    tags: ['izhe-source', 'teaching', 'names-of-god', 'give-one-catalogue', tag],
    credit: 'IZHE',
    notes: `${sourceNote} Blue IZHE wordmark on a white field with the question ${question}`,
    recommendedUse: RECOMMENDED_USE,
    technicalQuality: 'high',
    cropPotential: CROP,
    orientation: 'square',
    width: 2047,
    height: 2048,
    optimizedWidth: 2047,
    optimizedHeight: 2048,
    sourceType: 'repository_source',
    sourceOriginalPath,
    focalPoint: 'center',
    createdAt: CREATED_AT,
    updatedAt: CREATED_AT,
    static: true
  };
}

