// The supplied Your Friend? artwork is the same governed asset already produced by
// scripts/process_media.py. Enrich that existing record instead of creating a
// duplicate Media Library card for the same image.
export const NAMES_OF_GOD_SOURCE_MEDIA_OVERRIDES = {
  'source-izhe-question-friend-blue': {
    title: 'IZHE Your Friend? teaching mark',
    alt: 'Blue IZHE wordmark with the question Your Friend?',
    tags: ['names-of-god', 'give-one-catalogue', 'your-friend'],
    credit: 'IZHE',
    notes: 'Confirmed as one of the twelve IZHE Names of God / Give One teaching marks from the user-supplied Your Friend? artwork. The existing high-quality WebP source asset is retained to avoid duplicate media records.',
    recommendedUse: RECOMMENDED_USE
  }
};

export function applyNamesOfGodSourceMediaMetadata(item) {
  const override = NAMES_OF_GOD_SOURCE_MEDIA_OVERRIDES[item?.id];
  if (!override) return item;
  return {
    ...item,
    ...override,
    tags: [...new Set([...(item.tags || []), ...(override.tags || [])])]
  };
}
